// Fresh review implementation: enumerate every sorted quartet of coordinate IDs,
// assign it to its row/column margins, then compute exact row-space rank.
// Reads only integer sample tables generated by the review's Python checker.
#include <algorithm>
#include <array>
#include <cassert>
#include <chrono>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <map>
#include <vector>
using namespace std;
using Quartet = array<uint8_t,4>;
static uint64_t mix(uint64_t h,uint64_t x){return (h^x)*1099511628211ULL;}
template<unsigned P> int execute(const char* samples, bool control){
  ifstream in(samples); unsigned H[24][121];
  for(auto &row:H)for(auto &x:row){in>>x;if(!in||x>=P)return 2;}
  if(control)for(int r=1;r<24;r++)copy(H[0],H[0]+121,H[r]);
  vector<unsigned> inv(P);inv[1]=1;
  for(unsigned i=2;i<P;i++)inv[i]=P-(uint64_t(P/i)*inv[P%i])%P;
  vector<array<int,4>> margins; int mi[14641];fill(begin(mi),end(mi),-1);
  auto key=[](const array<int,4>&x){return ((x[0]*11+x[1])*11+x[2])*11+x[3];};
  for(int a=0;a<11;a++)for(int b=a;b<11;b++)for(int c=b;c<11;c++)for(int d=c;d<11;d++){
    array<int,4> q{a,b,c,d};mi[key(q)]=margins.size();margins.push_back(q);
  }
  assert(margins.size()==1001);vector<vector<Quartet>> groups(1002001);
  uint64_t generated=0, partition_hash=14695981039346656037ULL;
  for(int a=0;a<121;a++)for(int b=a;b<121;b++)for(int c=b;c<121;c++)for(int d=c;d<121;d++){
    array<int,4> r{a/11,b/11,c/11,d/11},s{a%11,b%11,c%11,d%11};
    sort(r.begin(),r.end());sort(s.begin(),s.end());int gid=mi[key(r)]*1001+mi[key(s)];assert(gid>=0);
    groups[gid].push_back(Quartet{uint8_t(a),uint8_t(b),uint8_t(c),uint8_t(d)});generated++;
    partition_hash=mix(partition_hash,(((uint64_t(a)*121+b)*121+c)*121+d));partition_hash=mix(partition_hash,gid);
  }
  assert(generated==9381251);
  auto rank=[&](unsigned M[24][24],int nr,int nc){
    int lead=0;
    for(int j=0;j<nc && lead<nr;j++){
      int found=lead;while(found<nr && M[found][j]==0)found++;
      if(found==nr)continue;
      for(int k=0;k<nc;k++)swap(M[lead][k],M[found][k]);
      unsigned scale=inv[M[lead][j]];
      for(int k=j;k<nc;k++)M[lead][k]=uint64_t(M[lead][k])*scale%P;
      for(int i=lead+1;i<nr;i++){
        unsigned f=M[i][j];if(!f)continue;M[i][j]=0;
        for(int k=j+1;k<nc;k++){
          unsigned v=uint64_t(f)*M[lead][k]%P;
          M[i][k]=M[i][k]>=v?M[i][k]-v:M[i][k]+P-v;
        }
      }
      lead++;
    }
    return lead;
  };
  map<int,uint64_t> histogram;uint64_t columns=0, blocks=0, initial_fail=0, final_fail=0;
  uint64_t ranks_hash=14695981039346656037ULL;auto start=chrono::steady_clock::now();
  const int ng=control?20020:1002001;
  for(int gid=0;gid<ng;gid++){
    const auto &Q=groups[gid];int k=Q.size();assert(k>=1&&k<=24);histogram[k]++;columns+=k;blocks++;
    unsigned values[24][24];
    auto prepare=[&](int rows){for(int r=0;r<rows;r++)for(int j=0;j<k;j++){
      uint64_t v=1;for(uint8_t coord:Q[j])v=v*H[r][coord]%P;values[r][j]=v;
    }};
    prepare(k);int rk=rank(values,k,k);int first=rk;
    if(rk<k){initial_fail++;prepare(24);rk=rank(values,24,k);cout<<"EXTRA_ROWS "<<gid/1001<<" "<<gid%1001<<" "<<k<<" "<<first<<" "<<rk<<"\n";}
    if(rk<k)final_fail++;
    ranks_hash=mix(mix(mix(ranks_hash,gid),first),rk);
    if(gid%100100==0)cerr<<"progress prime="<<P<<" blocks="<<gid+1<<" final_fail="<<final_fail<<"\n";
  }
  cout<<"PRIME "<<P<<"\nGENERATED "<<generated<<"\nPARTITION_FNV64 "<<partition_hash<<"\nBLOCKS "<<blocks<<"\nCOLUMNS "<<columns<<"\n";
  for(auto [k,n]:histogram)cout<<"HIST "<<k<<" "<<n<<"\n";
  cout<<"INITIAL_DEFICIENT "<<initial_fail<<"\nFINAL_DEFICIENT "<<final_fail<<"\nRANK_FNV64 "<<ranks_hash<<"\nSECONDS "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n";
  return control?(final_fail==18810?0:1):(final_fail?1:0);
}
int main(int argc,char**argv){if(argc<3)return 2;bool control=argc==4;return string(argv[1])=="1000003"?execute<1000003>(argv[2],control):execute<1000033>(argv[2],control);}
